select a.* from yh_health_lecture_info as a
INNER JOIN `yh_health_lecture_enshrine` AS b ON a.`infoId`=b.`categoryId` AND b.user_code=#{usercode}
INNER JOIN `yh_health_lecture_watch` AS b ON a.`infoId`=b.`class_id` AND b.user_code=#{usercode}
where
a.category_id IN (SELECT categoryId FROM `yh_health_lecture_category` WHERE `name` LIKE CONCAT('%',#{cateName},'%') OR tips LIKE CONCAT('%',#{cateName},'%'))
a.category_id=#{categoryId}
and a.title LIKE CONCAT('%',#{title},'%')
AND a.infoId NOT IN (SELECT class_id FROM yh_health_lecture_watch WHERE user_code=#{usercode} GROUP BY class_id)
order by a.infoId desc
order by a.read_count desc
limit #{curPage},#{pageSize}
